import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createApiKeysWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createApiKeysWorkflow(req.scope)
    .run({
      input: {
        api_keys: [{
          type: "publishable",
          title: "Storefront",
          created_by: "user_123"
        }]
      }
    })

  res.send(result)
}

